commands.command:
NODE1_ADDR=$(printf '%s\n' "$CLUSTER_HOSTS" | awk '$2 == "node1" { print $1; exit }')
test -n "$NODE1_ADDR" || { printf 'node1 address unavailable\n' >&2; exit 1; }
test -e /etc/nftables.conf.pre-prometheus-task || cp -a /etc/nftables.conf /etc/nftables.conf.pre-prometheus-task
cat > /etc/nftables.conf <<ANTRIEB_NFT_EOF
#!/usr/sbin/nft -f

flush ruleset

table inet filter {
    chain input {
        type filter hook input priority filter; policy accept;
        ip saddr $NODE1_ADDR tcp dport 9100 counter accept comment "allow Prometheus on node1"
        tcp dport 9100 counter reject with tcp reset comment "deny other node_exporter collectors"
    }

    chain forward {
        type filter hook forward priority filter; policy accept;
    }

    chain output {
        type filter hook output priority filter; policy accept;
    }
}
ANTRIEB_NFT_EOF
nft -c -f /etc/nftables.conf
printf 'nftables_config_valid node1=%s\n' "$NODE1_ADDR"

